// The tier-2 harness's assumptions about MATIEC's output shape, pinned against real
// generated files.
//
// Tier 2 (scripts/oracle-matiec.mjs --execute) can only run where MATIEC does, which is CI -
// so an assumption about what iec2c emits cannot be checked here without these fixtures. The
// ones pinned: the instance type carries a `_data__` suffix,
// POUS.c is textually included rather than compiled, every variable sits inside a
// `{value, flags}` record, and a TIME is a struct rather than a number. A wrong one masks the
// ones after it, so each would cost its own CI round trip to find.
//
// The fixtures below are excerpts of iec2c's actual output for a corpus case, so these
// assumptions are checked in the ordinary unit run with no toolchain present. If MATIEC's
// shape changes, this fails here rather than in a job that only runs on src/plc changes.
import { describe, expect, it } from 'vitest'
import { SHIM_DECLARATIONS, declaredTypes, locatedNames, parseInstance, parseInstances, renderHarness, translationUnits } from './oracleShape'

/** iec2c's resource file: the instance declaration, and the `#include "POUS.c"` that makes
 *  POUS.c part of this translation unit rather than one of its own. */
const RES0_C = `/* FILE GENERATED BY iec2c */
#include "iec_std_lib.h"
#include "accessor.h"
#include "POUS.h"
#include "Config0.h"
#define GLOBAL_CAST static
#include "POUS.c"

static BOOL TICK;
MAIN_data__ RES0__INST0;
#define INST0 RES0__INST0

void RES0_init__(void) {
  MAIN_init__(&INST0,retain);
}
`

/** iec2c's POU header: every variable declared through __DECLARE_VAR(type, NAME), with a
 *  function block's struct sitting above the program's. */
const POUS_H = `typedef struct {
  __DECLARE_VAR(BOOL,EN)
  __DECLARE_VAR(BOOL,IN)
  __DECLARE_VAR(TIME,PT)
} TON_data__;

// PROGRAM MAIN
typedef struct {
  // PROGRAM Interface - IN, OUT, IN_OUT variables
  __DECLARE_VAR(BOOL,GO)
  __DECLARE_VAR(BOOL,Q)
  __DECLARE_VAR(TIME,ET)
  __DECLARE_VAR(STRING,LABEL)

  // PROGRAM private variables
  TON_data__ T;

} MAIN_data__;
`

describe('discovering the generated program instance', () => {
  it('finds the _data__ struct type and the joined instance symbol', () => {
    // the original pattern was `^MAIN\s+(\w+);`, which cannot match `MAIN_data__ RES0__INST0;`
    expect(parseInstance(RES0_C, 'Main')).toEqual({ structType: 'MAIN_data__', instance: 'RES0__INST0' })
  })

  it('returns null when the shape changes, so the caller can say what it searched', () => {
    expect(parseInstance('nothing that looks like an instance\n', 'Main')).toBeNull()
  })
})

describe('a case with its own CONFIGURATION', () => {
  /** the resource file's instance lines for two instances of one PROGRAM type, and a task's
   *  static state, which must not be taken for an instance */
  const RES_TWO = `static BOOL FAST;
static R_TRIG_data__ SLOW_R_TRIG;
COUNTER_data__ RES0__FASTCOUNT;
#define FASTCOUNT RES0__FASTCOUNT
COUNTER_data__ RES0__SLOWCOUNT;
#define SLOWCOUNT RES0__SLOWCOUNT
`

  it('finds every program instance, with its name', () => {
    expect(parseInstances(RES_TWO)).toEqual([
      { name: 'FASTCOUNT', structType: 'COUNTER_data__', instance: 'RES0__FASTCOUNT' },
      { name: 'SLOWCOUNT', structType: 'COUNTER_data__', instance: 'RES0__SLOWCOUNT' },
    ])
  })

  const harness = renderHarness(
    { name: 'fixture', steps: [{ in: { 'SlowCount.go': true }, dt: 0.01 }] },
    {
      instance: 'RES0__FASTCOUNT',
      structType: 'COUNTER_data__',
      watched: [{ name: 'SlowCount.n', kind: 'int' }],
      instances: [
        { name: 'FASTCOUNT', symbol: 'RES0__FASTCOUNT', structType: 'COUNTER_data__', types: new Map([['N', 'INT']]) },
        { name: 'SLOWCOUNT', symbol: 'RES0__SLOWCOUNT', structType: 'COUNTER_data__', types: new Map([['N', 'INT'], ['GO', 'BOOL']]) },
      ],
    },
  )

  it('writes and reads Instance.Name on the instance it names', () => {
    expect(harness).toContain('extern COUNTER_data__ RES0__SLOWCOUNT;')
    expect(harness).toContain('RES0__SLOWCOUNT.GO.value = 1;')
    expect(harness).toContain('printf("%s\\"SLOWCOUNT.N\\":%lld", sep, (long long)(RES0__SLOWCOUNT.N.value));')
  })

  it("numbers ticks from 1, so a task's first scan comes one period in, as it does in this engine", () => {
    expect(harness).toContain('static unsigned long tick = 1;')
  })
})

describe('choosing the translation units', () => {
  it('drops a .c that another .c includes', () => {
    // POUS.c compiled on its own fails on its first line: its types come from the unit that
    // includes it
    const units = translationUnits([
      { name: 'Config0.c', text: '#include "iec_std_lib.h"\n' },
      { name: 'Res0.c', text: RES0_C },
      { name: 'POUS.c', text: '/* included by Res0.c */\n' },
    ])
    expect(units).toEqual(['Config0.c', 'Res0.c'])
  })
})

describe('reading the declared IEC types', () => {
  it('takes the types of THIS program struct, not a function block above it', () => {
    const types = declaredTypes(POUS_H, 'MAIN_data__')
    expect(types.get('ET')).toBe('TIME')
    expect(types.get('Q')).toBe('BOOL')
    expect(types.get('LABEL')).toBe('STRING')
    // PT belongs to TON_data__; a plain lazy match starts at the first `typedef struct` and
    // swallows it, which is exactly what this caught when the regex was written
    expect(types.has('PT')).toBe(false)
  })
})

describe('the generated harness', () => {
  const harness = renderHarness(
    { name: 'fixture', steps: [{ in: { go: true }, dt: 0.1 }] },
    {
      instance: 'RES0__INST0',
      structType: 'MAIN_data__',
      watched: [{ name: 'q', kind: 'int' }, { name: 'et', kind: 'real' }, { name: 'label', kind: 'string' }],
      types: declaredTypes(POUS_H, 'MAIN_data__'),
    },
  )

  it('externs the instance by its real type', () => {
    expect(harness).toContain('extern MAIN_data__ RES0__INST0;')
    expect(harness).toContain('static MAIN_data__ *inst = &RES0__INST0;')
  })

  it('reaches every variable through .value, since __DECLARE_VAR wraps it', () => {
    expect(harness).toContain('inst->GO.value = 1;')
    expect(harness).toContain('(long long)(inst->Q.value)')
  })

  it('flattens a TIME to milliseconds instead of casting the struct', () => {
    // IEC_TIME is a {tv_sec, tv_nsec} timespec: `(double)inst->ET.value` does not compile,
    // and the corpus states durations in ms
    expect(harness).toContain('(double)(inst->ET.value.tv_sec) * 1000.0 + (double)(inst->ET.value.tv_nsec) / 1e6')
  })

  it('reads a STRING as {len, body}, not as a char*', () => {
    expect(harness).toContain('emit_string(inst->LABEL.value.body, inst->LABEL.value.len)')
  })

  it('defines the shims MATIEC declares but never provides', () => {
    // iec_lib_* are left to the embedder; without them anything touching REAL math or
    // INT_TO_STRING fails to link, and -lm cannot help (the symbol is iec_lib_fmod)
    expect(harness).toContain('double iec_lib_fmod(double x, double y) { return fmod(x, y); }')
    expect(harness).toContain('int iec_lib_snprintf(')
    // _____time_* are emitted for +/-/* on TIME and declared in no matiec header
    expect(harness).toContain('TIME _____time_add(TIME a, TIME b) { return __time_add(a, b); }')
  })

  it("declares those shims for MATIEC's own units too", () => {
    // left implicit, C assumes `int` for a function returning a TIME struct: it links, and
    // then computes nonsense
    expect(SHIM_DECLARATIONS).toContain('TIME _____time_add(TIME a, TIME b);')
    expect(SHIM_DECLARATIONS).toContain('#include "iec_std_lib.h"')
  })

  it('reaches libc before matiec, in both the shim header and the harness', () => {
    // matiec's iec_std_functions.h defines function-like macros named __acos/__sqrt/__cos/
    // ..., the same reserved names glibc's <math.h> declares. Reversed, every math
    // declaration in glibc's header expands a macro and gcc rejects the lot. A Windows
    // clang replay does not reproduce it (MSVC's UCRT has no such aliases), so this ordering
    // is only ever protected by an assertion like this one.
    for (const text of [SHIM_DECLARATIONS, harness]) {
      expect(text.indexOf('#include <math.h>')).toBeGreaterThan(-1)
      expect(text.indexOf('#include <math.h>')).toBeLessThan(text.indexOf('#include "iec_std_lib.h"'))
    }
  })
})

describe('a program with located variables', () => {
  /** iec2c's POU header for `VAR Eye AT %IX0.0 : BOOL; Run AT %QX0.0 : BOOL; END_VAR` (measured) */
  const LOCATED_H = `// PROGRAM MAIN
// Data part
typedef struct {
  // PROGRAM Interface - IN, OUT, IN_OUT variables

  // PROGRAM private variables - TEMP, private and located variables
  __DECLARE_LOCATED(BOOL,EYE)
  __DECLARE_LOCATED(BOOL,RUN)
  __DECLARE_VAR(INT,N)

} MAIN_data__;
`

  it("reads a located variable's type, and knows it is located", () => {
    expect(declaredTypes(LOCATED_H, 'MAIN_data__')).toEqual(new Map([['EYE', 'BOOL'], ['RUN', 'BOOL'], ['N', 'INT']]))
    expect(locatedNames(LOCATED_H, 'MAIN_data__')).toEqual(new Set(['EYE', 'RUN']))
  })

  const harness = renderHarness(
    { name: 'fixture', steps: [{ in: { Eye: true }, dt: 0.1 }] },
    {
      instance: 'RES0__INST0',
      structType: 'MAIN_data__',
      watched: [{ name: 'Run', kind: 'int' }, { name: 'N', kind: 'int' }],
      types: declaredTypes(LOCATED_H, 'MAIN_data__'),
      located: locatedNames(LOCATED_H, 'MAIN_data__'),
    },
  )

  it('reaches a located payload through its pointer, and a plain one directly', () => {
    expect(harness).toContain('(*inst->EYE.value) = 1;')
    expect(harness).toContain('(long long)((*inst->RUN.value))')
    expect(harness).toContain('(long long)(inst->N.value)')
  })

  it('defines the storage MATIEC leaves to the runtime, values first and then the pointers to them', () => {
    // `__INIT_LOCATED` does `extern type *location; name.value = location;`: without these, the
    // replay failed to link with "undefined reference to __IX0_0"
    const values = harness.indexOf('#define __LOCATED_VAR(type, name, ...) type __##name;')
    const pointers = harness.indexOf('#define __LOCATED_VAR(type, name, ...) type *name = &__##name;')
    expect(values).toBeGreaterThan(-1)
    expect(pointers).toBeGreaterThan(values)
    expect(harness.split('#include "LOCATED_VARIABLES.h"')).toHaveLength(3)
  })
})
